script:
(() => {
    // Same card-list structure/technique as employee_list.js (see that
    // file's own comments for the full reasoning) - explicit user request
    // to match Employee's own FORMAT. Annual Payroll History is a CUSTOM
    // doctype (custom:1, Payroll Indonesia app's own install script built
    // it via frappe.get_doc().insert() rather than a committed module
    // .json+.py file) - Frappe's own FormMeta.add_code() has an early
    // `if self.custom: return` BEFORE it ever processes the
    // `doctype_list_js` hooks.py hook, so a garage-app .js file registered
    // there is silently never loaded for this doctype. Client Script
    // (view: "List") is the supported mechanism for custom doctypes
    // instead - FormMeta.add_custom_script() embeds it unconditionally,
    // with no `self.custom` guard. Same rendering logic as every other
    // card-list this session, just living in the database instead of
    // public/js/ for this one doctype.
    //
    // Submittable but has no `status` field of its own (unlike Payroll
    // Entry/Salary Slip) and no core listview_settings to extend - so the
    // Status badge is plain docstatus-based (Draft/Submitted/Cancelled,
    // same palette as payment_entry_list.js/salary_structure_assignment_
    // list.js elsewhere in this app). Column set is its own: Employee
    // Name/Fiscal Year/PPh21 Annual (the one figure this doctype exists to
    // compute - Indonesia's annual income tax reconciliation).
    const STATUS = {
        "0": { label: "Draft",     bg: "#f3f4f6", fg: "#4b5563" },
        "1": { label: "Submitted", bg: "#dcfce7", fg: "#15803d" },
        "2": { label: "Cancelled", bg: "#fee2e2", fg: "#b91c1c" },
    };

    function esc(v) { return frappe.utils.escape_html(v || ""); }

    const HEADER_HTML = `<div class="aph-header" style="
        display:flex !important;
        align-items:center;
        width:100%;
        padding:9px calc(14px + var(--padding-xs)) 9px var(--padding-xs);
        gap:10px;
        background:#1f2937;
    ">
        <div style="flex:0 0 36px;"></div>
        <span class="aph-c-id aph-hdr">ID</span>
        <span class="aph-c-emp aph-hdr">EMPLOYEE NAME</span>
        <span class="aph-c-year aph-hdr">FISCAL YEAR</span>
        <span class="aph-c-tax aph-hdr">PPH21 ANNUAL</span>
        <span class="aph-c-badge aph-hdr">STATUS</span>
        <span class="aph-c-ago aph-hdr"></span>
    </div>`;

    function card(doc) {
        const s = STATUS[String(doc.docstatus)] || STATUS["0"];
        const pph21 = doc.pph21_annual != null ? format_currency(doc.pph21_annual, "IDR") : "-";
        const ago = doc.modified ? frappe.datetime.comment_when(doc.modified, true) : "";

        return `<div class="aph-card" style="
            display:flex !important;
            align-items:center;
            width:100%;
            padding:10px 14px 10px 0;
            gap:10px;
            cursor:pointer;
        ">
            <div style="flex:0 0 36px; display:flex; align-items:center; justify-content:center;">
                <input type="checkbox" class="list-row-checkbox" data-name="${esc(doc.name)}" style="cursor:pointer;">
            </div>
            <span class="aph-c-id">${esc(doc.name)}</span>
            <span class="aph-c-emp">${esc(doc.employee_name)}</span>
            <span class="aph-c-year">${esc(doc.fiscal_year)}</span>
            <span class="aph-c-tax">${esc(pph21)}</span>
            <span class="aph-c-badge" style="background:${s.bg};color:${s.fg};">${esc(__(s.label))}</span>
            <span class="aph-c-ago">${ago}</span>
        </div>`;
    }

    function render(lv) {
        const $fl = lv.$result.closest(".frappe-list");
        if (!$fl.hasClass("aph-list")) $fl.addClass("aph-list");

        lv.$result.find(".list-row-head").each(function () {
            this.style.setProperty("display", "none", "important");
        });

        if (!$fl.find(".aph-header").length) {
            lv.$result.before(HEADER_HTML);
        }

        let idx = 0;
        lv.$result.find(".list-row:not(.list-row-head)").each(function () {
            const row = this;
            const $row = $(row);
            if ($row.hasClass("aph-ok")) return;

            const name = $row.find("input.list-row-checkbox").attr("data-name");
            const doc = (lv.data || []).find((d) => d.name === name);
            if (!doc) return;

            $row.addClass("aph-ok");

            $row.children().each(function () {
                this.style.setProperty("display", "none", "important");
            });

            row.style.setProperty("height", "auto", "important");
            row.style.setProperty("min-height", "0", "important");
            row.style.setProperty("padding", "0", "important");
            row.style.setProperty("overflow", "visible", "important");
            row.style.setProperty("background", "transparent", "important");

            const $card = $(card(doc));
            const bg = idx % 2 === 0 ? "#ffffff" : "#f0f1f3";
            $card[0].style.setProperty("background", bg, "important");
            $row.append($card);

            $card.on("mouseenter", function () {
                this.style.setProperty("background", "#e8edff", "important");
            }).on("mouseleave", function () {
                this.style.setProperty("background", bg, "important");
            });

            $card.on("click", function (e) {
                if ($(e.target).is("input[type=checkbox]")) return;
                frappe.set_route("Form", "Annual Payroll History", doc.name);
            });

            idx++;
        });
    }

    // No core listview_settings exists for Annual Payroll History to
    // extend.
    frappe.listview_settings["Annual Payroll History"] = {
        hide_name_column: true,
        add_fields: ["employee_name", "fiscal_year", "pph21_annual", "docstatus"],
        refresh(lv) {
            render(lv);
        },
    };
})();
